mapper.select:
select
id, activity_id, activity_name, activity_desc, strategy_id, condition_type,
condition_value, repeat_type, repeat_value, `state`, other_config,creator, create_time, update_time
from activity
where channel_id = #{channelId}
and activity_id = #{activityId}

SELECT a.id, a.activity_id, a.activity_name, a.activity_desc, a.state, a.update_time, s.order_amounts_rate, s.dividend_cycle, s.settlement_strategy, s.dividend_method, s.dividend_role FROM activity a LEFT JOIN strategy s ON a.strategy_id = s.strategy_id
a.activity_name like CONCAT( "%",#{req.activityName}, "%")
and s.dividend_cycle = #{req.dividendCycle}
and s.dividend_method = #{req.dividendMethod}
and a.state = #{req.state}
ORDER BY a.update_time DESC

mapper.update:
update activity
set `state` = #{state}
where channel_id = #{req.channelId}
and activity_id = #{req.activityId}
